head.script:
// 화면 리사이징
scwin.gLdMktTp;
scwin.gIsurCd;
scwin.threadID;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCode();
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        scwin.setHeader();
        scwin.init();
        await scwin.reloadAuto();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10910.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {

};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = function(row, colid) {
    try {
        scwin.setContnId(row);
        if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10910.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.reloadAuto();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10910.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal_onclick = function() {
    try {
        popUpCalendar2(edt_FromDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10910.img_FromCal_onclick" });
    }
};

/**
 * @method
 * @name img_ToCal_onclick
 * @description img_ToCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ToCal_onclick = function() {
    try {
        popUpCalendar2(edt_ToDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10910.img_ToCal_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_FromDate, edt_ToDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10910.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_Grid.errorMsg) {
            await $c.win.alert(dts_Grid.errorMsg);
        } else {
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10910.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10910.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10910.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10910.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10910.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10910.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
        scwin.clearIsurCd(); // 상장신청인
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10910.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF10910.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: '거래정지 요청 및 조치내역', type: 8});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10910.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10910.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10910.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10910.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10910.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10910.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name cmb_Company_onselchange
 * @description cmb_Company onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_Company_onselchange = async function() {
    try {
        await scwin.getJongmok($c.cp.valueOfIndex(cmb_Company, "VALUE", cmb_Company.getSelectedIndex()));
        scwin.clearComAbbrv();
        scwin.clearIsurCd();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10910.cmb_Company_onselchange" });
    }
};

/**
 * @method
 * @name cmb_Jongmok_onselchange
 * @description cmb_Jongmok onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_Jongmok_onselchange = function() {
    try {
        scwin.clearComAbbrv();
        scwin.clearIsurCd();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10910.cmb_Jongmok_onselchange" });
    }
};

/**
 * @method
 * @name txb_isur_cd2_onchange
 * @description txb_isur_cd2 변경 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd2_onchange = function() {
    try {
        txb_isur_nm2.setValue('');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10910.txb_isur_cd2_onchange" });
    }
};

/**
 * @method
 * @name img_isur_cd_onclick
 * @description img_isur_cd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_isur_cd_onclick = function() {
    try {
        fn_GetPar = scwin.getParIsur;
        fn_SetPar = scwin.setParIsur;
        $c.lcd.fn_PopFindDigitalIsurAll();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10910.img_isur_cd_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gLdMktTp = js_market;
    if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2' || scwin.gLdMktTp === '4' || scwin.gLdMktTp === '6') {
        rdo_MKT_ID.setValue(scwin.gLdMktTp);
        panel_mkt.hide();
    } else {
        rdo_MKT_ID.setValue('9');
    }
    if (scwin.gLdMktTp === '1') {
        panel_jongmok.style.visibility = "";
        panel_isur.style.visibility = ""; // 상장신청인

    }

    //  기간 from~ to  셋팅
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    // edt_FromDate.text = cGetMinusDate2(vCurDate, 365);     // 일주일전 날짜
    edt_FromDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 발행회사
    const sbmOptions = {
        id : "sbm_dts_CompanyList",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_CompanyList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_Jongmok",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_Jongmok=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/MktActNotice.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getJongmok
 * @description get Jongmok 처리
 * @param {*} gubun gubun
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getJongmok = async function(gubun) {
    const sbmOptions = {
        id : "sbm_dts_Jongmok",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_Jongmok=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setHeader
 * @description CUD용 Header
 * @returns {void}
 * @hidden N
 */
scwin.setHeader = function() {
    // CUD용 Header

};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gIsurCd = dts_Grid.getCellData(Number(obj), "ISUR_CD");
};

/**
 * @method
 * @name reloadAuto
 * @description reload Auto 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reloadAuto = async function() {
    scwin.stopReload();
    scwin.threadID = setInterval('fn_list_sync()', 30000); // 30초
    await scwin.listSync();
};

/**
 * @method
 * @name stopReload
 * @description stop Reload 처리
 * @returns {void}
 * @hidden N
 */
scwin.stopReload = function() {
    clearInterval(scwin.threadID);
};

/**
 * @method
 * @name clearJongmok
 * @description clear Jongmok 처리
 * @returns {void}
 * @hidden N
 */
scwin.clearJongmok = function() {
    cmb_Company.setValue('');
    cmb_Jongmok.setValue('');
};

/**
 * @method
 * @name clearComAbbrv
 * @description clear Com Abbrv 처리
 * @returns {void}
 * @hidden N
 */
scwin.clearComAbbrv = function() {
    txb_isur_cd.setValue('');
    txb_com_abbrv.setValue('');
};

/**
 * @method
 * @name clearIsurCd
 * @description 상장신청인 clear
 * @returns {void}
 * @hidden N
 */
scwin.clearIsurCd = function() {
    if ((txb_isur_cd.getValue() !== '') || (cmb_Company.getValue() !== '')) {
        txb_isur_cd2.setValue('');
        txb_isur_nm2.setValue('');
    }
};

/**
 * @method
 * @name getParIsur
 * @description dialog 호출용 함수 디지털증권 상장신청인 호출관련
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션

    arrPar[0] = txb_isur_cd2.getValue(); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_isur_nm2.getValue(); // 명칭값을 포함할 컨트롤

    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_isur_cd2.setValue(arrPar[0].ISUR_CD);
        txb_isur_nm2.setValue(arrPar[0].ISUR_NM);
        scwin.clearComAbbrv();
        scwin.clearJongmok();
    }
};
